import { BadRequestException, Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Column, Entity, PrimaryGeneratedColumn, Repository } from 'typeorm';

export enum RefundStatus {
  PENDING = 'PENDING',
  SUCCEEDED = 'SUCCEEDED',
  FAILED = 'FAILED',
}

@Entity('payments')
export class Payment {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column()
  orderId: string;

  // Ceiling that all refunds against this order must respect, in cents.
  @Column('int')
  capturedAmount: number;
}

// The refund ledger: the source of truth for how much has actually been refunded.
@Entity('refunds')
export class Refund {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column()
  orderId: string;

  @Column('int')
  amount: number;

  @Column({ type: 'enum', enum: RefundStatus })
  status: RefundStatus;

  @Column()
  idempotencyKey: string;

  @Column({ type: 'varchar', nullable: true })
  gatewayRefundId: string | null;
}

export interface PaymentGatewayClient {
  refund(amount: number): Promise<{ gatewayRefundId: string }>;
}

@Injectable()
export class RefundService {
  // Service-side idempotency lookup: LAYER 1 only. There is no equivalent
  // dedup key forwarded to the gateway, so this guards the service boundary alone.
  private readonly idempotencyStore = new Map<string, Refund>();

  constructor(
    @InjectRepository(Payment)
    private readonly paymentRepository: Repository<Payment>,
    @InjectRepository(Refund)
    private readonly refundRepository: Repository<Refund>,
    private readonly paymentGateway: PaymentGatewayClient,
  ) {}

  async refund(orderId: string, amount: number, idempotencyKey: string): Promise<Refund> {
    // 1. Idempotency check (layer 1 only): a prior record for this key short-circuits.
    const existing = this.idempotencyStore.get(idempotencyKey);
    if (existing) {
      return existing;
    }

    const payment = await this.paymentRepository.findOneByOrFail({ orderId });

    // 2. Amount check considers only THIS request in isolation. It never
    // recomputes remainingRefundable = capturedAmount - sum(SUCCEEDED refunds)
    // from the ledger, so three sequential 60% partial refunds each pass this
    // check individually while summing to 180% of the captured amount.
    if (amount > payment.capturedAmount) {
      throw new BadRequestException('Refund amount exceeds captured amount');
    }

    // 3. Gateway call does not forward idempotencyKey, so the gateway has no
    // dedup entry of its own and will treat any retry as a brand-new refund.
    const gatewayResult = await this.paymentGateway.refund(amount);

    // 4. Ledger write happens AFTER the gateway call returns. If the process
    // crashes in this gap, a client retry finds no service-side record (layer 1
    // misses, since the map was never populated) and the gateway has no dedup
    // entry either (layer 2 absent) -> a second real refund goes out.
    const refund = this.refundRepository.create({
      orderId,
      amount,
      status: RefundStatus.SUCCEEDED,
      idempotencyKey,
      gatewayRefundId: gatewayResult.gatewayRefundId,
    });
    await this.refundRepository.save(refund);

    this.idempotencyStore.set(idempotencyKey, refund);
    return refund;
  }
}
